-- Creates the users and user_sessions tables.
--
-- A user signs in with an email and a password. The email is stored in lower
-- case, so it is unique after lower-case normalization. The password is stored
-- only as a salted scrypt hash in PHC string format. A session is an opaque
-- token stored as a public lookup identifier and the SHA-256 hash of its secret
-- part, like an API key. Timestamps have no database default: the application
-- supplies them from its injected clock. Identifiers are UUIDs generated by the
-- application.

CREATE TABLE users (
  id uuid NOT NULL,
  email varchar(254) NOT NULL,
  display_name varchar(100) NOT NULL,
  role varchar(20) NOT NULL,
  merchant_id uuid,
  password_hash varchar(200) NOT NULL,
  enabled boolean NOT NULL,
  created_at timestamptz NOT NULL,
  updated_at timestamptz NOT NULL,
  CONSTRAINT users_pkey PRIMARY KEY (id),
  CONSTRAINT users_email_key UNIQUE (email),
  CONSTRAINT users_merchant_id_fkey FOREIGN KEY (merchant_id) REFERENCES merchants (id),
  -- Lower-case ASCII only, one @, and a domain with at least one dot. Together
  -- with the unique constraint, two emails that differ only in case cannot both
  -- exist.
  CONSTRAINT users_email_check CHECK (
    email ~ '^[a-z0-9.!#$%&''*+/=?^_`{|}~-]+@[a-z0-9-]+(\.[a-z0-9-]+)+$'
  ),
  CONSTRAINT users_display_name_check CHECK (display_name ~ '\S'),
  -- Same pairing as api_keys_role_scope_check: a platform user has no merchant
  -- and the platform administrator role; a merchant user references a merchant
  -- and has a merchant role.
  CONSTRAINT users_role_scope_check CHECK (
    (merchant_id IS NULL AND role = 'PLATFORM_ADMIN')
    OR (merchant_id IS NOT NULL AND role IN ('MERCHANT_ADMIN', 'MERCHANT_READ_ONLY'))
  ),
  -- PHC string: $scrypt$ln=<log2 N>,r=<r>,p=<p>$<salt>$<hash>, both in
  -- unpadded standard base64.
  CONSTRAINT users_password_hash_check CHECK (
    password_hash ~ '^\$scrypt\$ln=[0-9]{1,2},r=[0-9]{1,2},p=[0-9]{1,2}\$[A-Za-z0-9+/]{16,}\$[A-Za-z0-9+/]{32,}$'
  ),
  CONSTRAINT users_updated_at_check CHECK (updated_at >= created_at)
);

COMMENT ON TABLE users IS 'People who sign in to the web frontend. Passwords are stored only as salted scrypt hashes.';
COMMENT ON COLUMN users.email IS 'Sign-in identifier, stored in lower case.';
COMMENT ON COLUMN users.merchant_id IS 'The merchant the user belongs to. NULL for a platform user.';
COMMENT ON COLUMN users.password_hash IS 'scrypt hash in PHC string format, with its own salt and parameters. Never the password.';
COMMENT ON COLUMN users.enabled IS 'A disabled user cannot sign in, and its existing sessions stop authenticating.';

-- The identity and authority of a user never change: a session that was issued
-- for one role and merchant must not gain another.
CREATE FUNCTION users_reject_scope_update() RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF (NEW.id, NEW.role, NEW.merchant_id, NEW.created_at)
     IS DISTINCT FROM
     (OLD.id, OLD.role, OLD.merchant_id, OLD.created_at) THEN
    RAISE EXCEPTION 'users: id, role, merchant_id, and created_at cannot be changed'
      USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER users_restrict_update
BEFORE UPDATE ON users
FOR EACH ROW
EXECUTE FUNCTION users_reject_scope_update();

CREATE TABLE user_sessions (
  id uuid NOT NULL,
  user_id uuid NOT NULL,
  lookup_id varchar(16) NOT NULL,
  secret_hash varchar(64) NOT NULL,
  created_at timestamptz NOT NULL,
  expires_at timestamptz NOT NULL,
  revoked_at timestamptz,
  CONSTRAINT user_sessions_pkey PRIMARY KEY (id),
  CONSTRAINT user_sessions_lookup_id_key UNIQUE (lookup_id),
  CONSTRAINT user_sessions_user_id_fkey FOREIGN KEY (user_id) REFERENCES users (id),
  -- 8 random bytes in lowercase hexadecimal.
  CONSTRAINT user_sessions_lookup_id_check CHECK (lookup_id ~ '^[0-9a-f]{16}$'),
  -- SHA-256 digest in lowercase hexadecimal.
  CONSTRAINT user_sessions_secret_hash_check CHECK (secret_hash ~ '^[0-9a-f]{64}$'),
  CONSTRAINT user_sessions_expires_at_check CHECK (expires_at > created_at)
);

CREATE INDEX user_sessions_user_id_idx ON user_sessions (user_id);

COMMENT ON TABLE user_sessions IS 'Sign-in sessions of users. Only the lookup identifier and the SHA-256 hash of the token secret are stored.';
COMMENT ON COLUMN user_sessions.lookup_id IS 'Public identifier embedded in the token, used to find the row before the secret is compared.';
COMMENT ON COLUMN user_sessions.secret_hash IS 'SHA-256 of the secret part of the token, as 64 lowercase hexadecimal characters. Safe because the secret has 256 bits of entropy.';
COMMENT ON COLUMN user_sessions.expires_at IS 'Absolute expiry. The session never authenticates at or after this time.';
COMMENT ON COLUMN user_sessions.revoked_at IS 'Set once by sign-out. A session with a value here never authenticates again.';

-- Only revoked_at can change, and only from NULL to a value, so a revoked or
-- expired session cannot be reactivated or extended.
CREATE FUNCTION user_sessions_reject_invalid_update() RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF (NEW.id, NEW.user_id, NEW.lookup_id, NEW.secret_hash, NEW.created_at, NEW.expires_at)
     IS DISTINCT FROM
     (OLD.id, OLD.user_id, OLD.lookup_id, OLD.secret_hash, OLD.created_at, OLD.expires_at) THEN
    RAISE EXCEPTION 'user_sessions: only revoked_at can be changed'
      USING ERRCODE = 'restrict_violation';
  END IF;
  IF OLD.revoked_at IS NOT NULL AND NEW.revoked_at IS DISTINCT FROM OLD.revoked_at THEN
    RAISE EXCEPTION 'user_sessions: a revoked session cannot be reactivated or revoked again'
      USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER user_sessions_restrict_update
BEFORE UPDATE ON user_sessions
FOR EACH ROW
EXECUTE FUNCTION user_sessions_reject_invalid_update();
